package com.ChaTop.Backend.Responses;public class MessageResponse {    private int id;    private String message;    private int userId;    private int rentalId;    public int getId() {        return id;    }    public void setId(int id) {        this.id = id;    }    public String getMessage() {        return message;    }    public void setMessage(String message) {        this.message = message;    }    public int getUserId() {        return userId;    }    public void setUserId(int userId) {        this.userId = userId;    }    public int getRentalId() {        return rentalId;    }    public void setRentalId(int rentalId) {        this.rentalId = rentalId;    }}